/**
 * One key in this relay's admitted set, the result of folding dinner, join, device and revoke from the circle root.
 */
export interface AdmittedKey {
  key: string;
  role: KeyRole;
  /** The identity key this key belongs to (itself, for an identity key). */
  identity: string;
  /** relay_id of the message that admitted it. */
  admitted_at: number;
  /** The member's join epoch, the floor for the content they may fetch. */
  join_epoch: number;
  /** relay_id of the revoke, when revoked. */
  revoked_at?: number;
  /** For a revoked device key, the cutoff from its revoke's after_seq: the highest seq nodes still read from it. 0 when the revoke stopped it without listing it. */
  after_seq?: number;
}

export interface AppendReceipt {
  status: AppendStatus;
  relay_id: number;
  hash: string;
}

export interface Circle {
  /** sha256:<hex> of the founding dinner envelope this relay is configured with. */
  root: string;
  /** The current epoch by this relay's fold. */
  epoch: number;
  keys: AdmittedKey[];
  limits: RelayLimits;
}

/**
 * One signed, immutable message. The signature covers the canonical encoding of every field but signature itself, and body_hash binds the body, so a relay can drop a retracted body and the envelope still verifies.
 */
export interface Envelope {
  /** Envelope version, 2. Bumped by protocol changes; 2 is the revoke body carrying after_seq and mail_read. Any other version is refused. */
  version: number;
  /** The signing key, ed25519:<base64url>. A device or mail key; an invite key on a join's outer envelope; the host's device key on a dinner. */
  author: string;
  /** Strictly increasing per chained author. Gaps are expected only for mail keys. */
  seq: number;
  /** sha256:<hex> of the author's previous envelope. Absent on an author's first envelope. For a mail key, the hash of the ask being answered. */
  prev?: string;
  /** The author's clock. Informational; ordering comes from seq per author and relay_id per relay. */
  created_at: ISODateTimeString;
  /** Increments on every join. A newcomer reads content from their join epoch forward. */
  epoch: number;
  kind: Kind;
  /** sha256:<hex> of the canonical encoding of the body. */
  body_hash: string;
  /** ed25519 signature by author, base64url. */
  signature: string;
}

export interface EnvelopePage {
  envelopes: StoredEnvelope[];
  /** Pass as after to fetch the next page. Absent when the reader is caught up. */
  next?: number;
}

/**
 * The confirm page's form, posted form-encoded.
 */
export interface LinkConfirmForm {
  /** The link secret, base64url, from the link the person opened. */
  s: string;
}

export interface MailReceipt {
  status: MailStatus;
  digest: string;
}

/**
 * Asks the mailing relay to email a digest it holds. The link secrets ride only here, sealed to the mailing relay's key, and the relay never stores them.
 */
export interface MailRequest {
  /** sha256:<hex> of the digest envelope, appended before this request. */
  digest: string;
  /** Sealed to the mailing relay's key (docs/protocol.md, Sealing); the plaintext is { links: [ { id, secret } ] }. */
  sealed: any;
}

export interface RelayError {
  code: ErrorCode;
  message: string;
}

export interface RelayLimits {
  /** Envelope plus body. Default 65536. */
  max_envelope_bytes: number;
  /** Default 500, UTC day. */
  max_appends_per_device_per_day: number;
  /** Default 500. */
  max_page_size: number;
  /** Default 3600. */
  skew_seconds: number;
}

/**
 * What a node appends and a relay stores: the envelope and the body beside it.
 */
export interface SignedEnvelope {
  envelope: Envelope;
  /** The body, whose shape is fixed by kind (docs/protocol.md). Absent when a retract dropped it or the reader may not see it. */
  body?: any;
}

export interface StoredEnvelope {
  /** Assigned by this relay, only ever increasing. Cursors are per relay; nodes dedupe by envelope hash across relays. */
  relay_id: number;
  /** sha256:<hex> of the canonical envelope including its signature. */
  hash: string;
  envelope: Envelope;
  body?: any;
  received_at: ISODateTimeString;
}

